<?php
require_once __DIR__ . '/../includes/helpers.php'; verify_csrf(); $token=$_GET['token'] ?? $_POST['token'] ?? ''; $error='';
$stmt=db()->prepare('SELECT pr.*, u.full_name FROM password_resets pr JOIN users u ON u.id=pr.user_id WHERE pr.token=? AND pr.used=0 AND pr.expiry_time > NOW() LIMIT 1'); $stmt->bind_param('s',$token); $stmt->execute(); $reset=$stmt->get_result()->fetch_assoc();
if(!$reset) $error='Reset token is invalid, expired, or already used.';
if($_SERVER['REQUEST_METHOD']==='POST' && $reset){ $p=$_POST['password']??''; $c=$_POST['confirm_password']??''; if($p!==$c) $error='Passwords do not match.'; elseif($e=password_policy_error($p)) $error=$e; else { $hash=password_hash($p,PASSWORD_BCRYPT); $stmt=db()->prepare('UPDATE users SET password_hash=?, must_change_password=0, failed_attempts=0, locked_until=NULL WHERE id=?'); $stmt->bind_param('si',$hash,$reset['user_id']); $stmt->execute(); $stmt=db()->prepare('UPDATE password_resets SET used=1 WHERE id=?'); $stmt->bind_param('i',$reset['id']); $stmt->execute(); audit('password_reset_completed','user',(int)$reset['user_id']); flash('success','Password updated. Please login.'); redirect('login.php'); } }
?>
<!DOCTYPE html><html><head><meta name="viewport" content="width=device-width, initial-scale=1"><title>Reset Password</title><link rel="stylesheet" href="<?= BASE_URL ?>/assets/css/style.css"></head><body class="auth-body"><section class="auth-card"><h1>Reset Password</h1><?php if($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><?php if($reset): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="token" value="<?= e($token) ?>"><label>New password<input type="password" name="password" required></label><label>Confirm password<input type="password" name="confirm_password" required></label><button class="btn btn-primary full">Save password</button></form><?php endif; ?></section></body></html>
